   346	static int sf32lb52_bt_forward_packet(struct sf32lb52_bt_priv_s *priv,
   347	                                      uint8_t *data, size_t len)
   348	{
   349	  enum bt_buf_type_e type;
   350	  int ret;
   351	
   352	  if (len <= H4_HEADER_SIZE)
   353	    {
   354	      return -EINVAL;
   355	    }
   356	
   357	  switch (data[0])
   358	    {
   359	      case H4_EVT:
   360	        if (len >= H4_HEADER_SIZE + sizeof(struct bt_hci_evt_hdr_s) +
   361	                   sizeof(struct bt_hci_evt_disconn_complete_s) &&
   362	            data[H4_HEADER_SIZE] == BT_HCI_EVT_DISCONN_COMPLETE &&
   363	            data[H4_HEADER_SIZE + 1] >=
   364	              sizeof(struct bt_hci_evt_disconn_complete_s))
   365	          {
   366	            const size_t params_offset =
   367	              H4_HEADER_SIZE + sizeof(struct bt_hci_evt_hdr_s);
   368	
   369	            syslog(LOG_INFO,
   370	                   "sf32lb52 bth4 disconnect: status=0x%02x "
   371	                   "handle=0x%04x reason=0x%02x\n",
   372	                   data[params_offset],
   373	                   sf32lb52_bt_get_le16(&data[params_offset + 1]),
   374	                   data[params_offset + 3]);
   375	          }
   376	
   377	        #if SF32LB52_BT_NORMALIZE_RESET_STATUS
   378	          sf32lb52_bt_normalize_event(data, len);
   379	        #endif
   380	        type = BT_EVT;
   381	        break;
   382	
   383	      case H4_ACL:
   384	        type = BT_ACL_IN;
   385	        break;
   386	
   387	      case H4_ISO:
   388	        type = BT_ISO_IN;
   389	        break;
   390	
   391	      default:
   392	        return -EINVAL;
   393	    }
   394	
   395	  ret = bt_netdev_receive(&priv->drv,
   396	                          type,
   397	                          (void *)&data[H4_HEADER_SIZE],
   398	                          len - H4_HEADER_SIZE);
   399	  if (ret < 0)
   400	    {
   401	      wlerr("Failed to receive HCI packet: %d\n", ret);
   402	    }
   403	
   404	  return ret;
   405	}
