555	  .drv =
556	    {
557	      .head_reserve = H4_HEADER_SIZE,
558	      .open         = sf32lb52_bt_open,
559	      .send         = sf32lb52_bt_send,
560	      .close        = sf32lb52_bt_close,
561	    },
562	};
