785	static void sf32lb52_bt_close(struct bt_driver_s *drv)
786	{
787	  int ret;
788	
789	  (void)drv;
790	
791	  g_sf32lb52_bt_priv.rxlen = 0;
792	
793	  /* Full deinit (not just disable) so that the next open re-initialises
794	   * the IPC queue from a clean state.  Without deinit, controller_init
795	   * is skipped on re-open (status != IDLE), and LCPU's ring-buffer
796	   * read pointer (reset on power-on) diverges from HCPU's stale write
797	   * pointer, causing all HCI commands to be silently dropped. */
798	  ret = sf32lb52_bt_controller_deinit();
799	  if (ret < 0)
800	    {
