745	static int sf32lb52_bt_ensure_controller_enabled(uint16_t opcode)
746	{
747	  int ret;
748	
749	  ret = sf32lb52_bt_controller_enable();
750	  if (ret < 0)
751	    {
752	      syslog(LOG_ERR,
753	             "sf32lb52 bth4 controller enable failed before opcode=0x%04x: %d\n",
754	             opcode,
755	             ret);
756	    }
757	
758	  return ret;
759	}
