564	static int sf32lb52_bt_recv_cb(uint8_t *data, uint16_t len)
565	{
566	  struct sf32lb52_bt_priv_s *priv = &g_sf32lb52_bt_priv;
567	  ssize_t packet_len;
568	  int ret;
569	
570	  if (data == NULL || len == 0)
571	    {
572	      return -EINVAL;
573	    }
574	
575	  if (priv->drop_rx_until_tx)
576	    {
577	      return OK;
578	    }
579	
580	  if (priv->rxlen + len > sizeof(priv->rxbuf))
581	    {
582	      syslog(LOG_ERR,
583	             "sf32lb52 bth4 rx overflow: pending=%lu incoming=%u\n",
584	             (unsigned long)priv->rxlen,
585	             len);
586	      priv->rxlen = 0;
587	    }
588	
589	  memcpy(&priv->rxbuf[priv->rxlen], data, len);
590	  priv->rxlen += len;
591	
592	#if SF32LB52_BT_TRACE
593	  if (priv->rxbuf[0] != H4_ACL || SF32LB52_BT_TRACE_ACL)
594	    {
595	      syslog(LOG_INFO,
596	             "sf32lb52 bth4 recv: len=%u pending=%lu first=%02x\n",
597	             len, (unsigned long)priv->rxlen, priv->rxbuf[0]);
598	    }
599	#endif
600	
601	  ret = OK;
602	
603	  while (priv->rxlen > 0)
604	    {
605	      packet_len = sf32lb52_bt_h4_packet_len(priv->rxbuf, priv->rxlen);
606	      if (packet_len == 0)
607	        {
608	          break;
609	        }
610	
611	      if (packet_len < 0)
612	        {
613	          syslog(LOG_WARNING,
614	                 "sf32lb52 bth4 drop invalid h4 type=%02x pending=%lu\n",
615	                 priv->rxbuf[0],
616	                 (unsigned long)priv->rxlen);
617	          memmove(priv->rxbuf, &priv->rxbuf[1], priv->rxlen - 1);
618	          priv->rxlen--;
619	          ret = -EINVAL;
620	          continue;
621	        }
622	
623	      if ((size_t)packet_len > priv->rxlen)
624	        {
625	          break;
626	        }
627	
628	#if SF32LB52_BT_TRACE_ATT
629	      sf32lb52_bt_trace_att("RX", priv->rxbuf, (size_t)packet_len);
630	#endif
631	
632	      ret = sf32lb52_bt_forward_packet(priv, priv->rxbuf,
633	                   (size_t)packet_len);
634	
635	      priv->rxlen -= (size_t)packet_len;
636	      if (priv->rxlen > 0)
637	        {
638	          memmove(priv->rxbuf,
639	                  &priv->rxbuf[packet_len],
640	                  priv->rxlen);
641	        }
642	    }
643	
644	  return ret;
645	}
646	
647	static int sf32lb52_bt_send(struct bt_driver_s *drv,
648	                            enum bt_buf_type_e type,
649	                            void *data, size_t len)
650	{
651	  struct sf32lb52_bt_priv_s *priv = &g_sf32lb52_bt_priv;
652	  uint8_t *hdr = (uint8_t *)data - drv->head_reserve;
653	  uint16_t opcode;
654	  int ret;
655	
656	  switch (type)
657	    {
658	      case BT_CMD:
659	        *hdr = H4_CMD;
660	        break;
661	      case BT_ACL_OUT:
662	        *hdr = H4_ACL;
663	        break;
664	      case BT_ISO_OUT:
665	        *hdr = H4_ISO;
666	        break;
667	      default:
668	        return -EINVAL;
669	    }
670	
671	  if (type == BT_CMD && len >= sizeof(struct bt_hci_cmd_hdr_s))
672	    {
673	      opcode = sf32lb52_bt_get_le16(data);
674	
675	  #if SF32LB52_BT_TRACE
676	    syslog(LOG_INFO,
677	            "sf32lb52 bth4 hci tx: opcode=0x%04x len=%lu\n",
678	            opcode, (unsigned long)len);
679	    #endif
680	
681	  #if SF32LB52_BT_COMPAT_BR_INIT
682	    if (opcode == BT_HCI_OP_WRITE_LOCAL_NAME)
683	      {
684	        syslog(LOG_INFO,
685	               "sf32lb52 bth4 compat: synth BR init opcode=0x%04x\n",
686	               opcode);
687	        ret = sf32lb52_bt_synth_status_complete(priv, opcode);
688	        return ret < 0 ? ret : len;
689	      }
690	    #endif
691	
692	  #if SF32LB52_BT_EMULATE_HCI
693	    if (sf32lb52_bt_emulate_cmd(priv, opcode, &ret))
694	    {
695	      return ret < 0 ? ret : len;
696	    }
697	    #endif
698	
699	  ret = sf32lb52_bt_ensure_controller_enabled(opcode);
700	      if (ret < 0)
701	        {
702	          return ret;
703	        }
704	    }
705	  else
706	    {
707	      ret = sf32lb52_bt_ensure_controller_enabled(0);
708	      if (ret < 0)
709	        {
710	          return ret;
711	        }
712	    }
713	
714	  priv->drop_rx_until_tx = false;
715	
716	  if (SF32LB52_BT_TRACE_ACL && type == BT_ACL_OUT)
717	    {
718	      syslog(LOG_INFO,
719	             "sf32lb52 bth4 tx: type=%u len=%lu h4=%02x acl=%02x %02x %02x %02x\n",
720	             (unsigned int)type,
721	             (unsigned long)(len + drv->head_reserve),
722	             hdr[0],
723	             len >= 1 ? hdr[1] : 0,
724	             len >= 2 ? hdr[2] : 0,
725	             len >= 3 ? hdr[3] : 0,
726	             len >= 4 ? hdr[4] : 0);
727	    }
728	
729	#if SF32LB52_BT_TRACE_ATT
730	  if (type == BT_ACL_OUT)
731	    {
732	      sf32lb52_bt_trace_att("TX", hdr, len + drv->head_reserve);
733	    }
734	#endif
735	
736	  ret = sf32lb52_host_send_packet(hdr, len + drv->head_reserve);
737	  if (ret < 0)
738	    {
739	      return ret;
740	    }
741	
742	  return len;
743	}
