564	static int sf32lb52_bt_recv_cb(uint8_t *data, uint16_t len)
565	{
566	  struct sf32lb52_bt_priv_s *priv = &g_sf32lb52_bt_priv;
567	  ssize_t packet_len;
568	  int ret;
569	
570	  if (data == NULL || len == 0)
571	    {
572	      return -EINVAL;
573	    }
574	
575	  if (priv->drop_rx_until_tx)
576	    {
577	      return OK;
578	    }
579	
580	  if (priv->rxlen + len > sizeof(priv->rxbuf))
581	    {
582	      syslog(LOG_ERR,
583	             "sf32lb52 bth4 rx overflow: pending=%lu incoming=%u\n",
584	             (unsigned long)priv->rxlen,
585	             len);
586	      priv->rxlen = 0;
587	    }
588	
589	  memcpy(&priv->rxbuf[priv->rxlen], data, len);
590	  priv->rxlen += len;
591	
592	#if SF32LB52_BT_TRACE
593	  if (priv->rxbuf[0] != H4_ACL || SF32LB52_BT_TRACE_ACL)
594	    {
595	      syslog(LOG_INFO,
596	             "sf32lb52 bth4 recv: len=%u pending=%lu first=%02x\n",
597	             len, (unsigned long)priv->rxlen, priv->rxbuf[0]);
598	    }
599	#endif
600	
601	  ret = OK;
602	
603	  while (priv->rxlen > 0)
604	    {
605	      packet_len = sf32lb52_bt_h4_packet_len(priv->rxbuf, priv->rxlen);
606	      if (packet_len == 0)
607	        {
608	          break;
609	        }
610	
611	      if (packet_len < 0)
612	        {
613	          syslog(LOG_WARNING,
614	                 "sf32lb52 bth4 drop invalid h4 type=%02x pending=%lu\n",
615	                 priv->rxbuf[0],
616	                 (unsigned long)priv->rxlen);
617	          memmove(priv->rxbuf, &priv->rxbuf[1], priv->rxlen - 1);
618	          priv->rxlen--;
619	          ret = -EINVAL;
620	          continue;
621	        }
622	
623	      if ((size_t)packet_len > priv->rxlen)
624	        {
625	          break;
626	        }
627	
628	#if SF32LB52_BT_TRACE_ATT
629	      sf32lb52_bt_trace_att("RX", priv->rxbuf, (size_t)packet_len);
630	#endif
631	
632	      ret = sf32lb52_bt_forward_packet(priv, priv->rxbuf,
633	                   (size_t)packet_len);
634	
635	      priv->rxlen -= (size_t)packet_len;
636	      if (priv->rxlen > 0)
637	        {
638	          memmove(priv->rxbuf,
639	                  &priv->rxbuf[packet_len],
640	                  priv->rxlen);
641	        }
642	    }
643	
644	  return ret;
645	}
