884	int sf32lb52_host_send_packet(const uint8_t *data, uint16_t len)
884	int sf32lb52_host_send_packet(const uint8_t *data, uint16_t len)
885	{
885	{
886	  struct circular_buf *tx_ring =
887	      (struct circular_buf *)SF32LB52_BT_TX_BUF_ADDR;
888	  uint32_t start_time;
889	  uint32_t tick_count;
890	  size_t written;
891	  size_t remaining;
892	  size_t offset;
893	  size_t chunk;
894	  size_t chunks;
895	  uint32_t wr_ptr;
896	  int ret;
897	
898	  if (data == NULL || len == 0)
899	    {
900	      return -EINVAL;
901	    }
902	
903	  if (g_sf32lb52_bt_status != SF32LB52_BT_STATUS_ENABLED ||
904	      !g_sf32lb52_bt_env.queue_open)
905	    {
906	      return -ENODEV;
907	    }
908	
909	  offset = 0;
910	  remaining = len;
911	  start_time = HAL_GetTick();
912	  tick_count = 0;
913	  chunks = 0;
914	  wr_ptr = 0;
915	
916	  ret = sf32lb52_bt_wait_tx_idle(tx_ring);
917	  if (ret < 0)
918	    {
919	      return ret;
920	    }
921	
922	  while (remaining > 0)
923	    {
924	      irqstate_t flags;
925	
926	      chunk = sf32lb52_bt_tx_chunk_len(data, len, offset);
927	
928	      up_invalidate_dcache((uintptr_t)SF32LB52_BT_TX_BUF_ADDR,
929	                           (uintptr_t)SF32LB52_BT_TX_BUF_ADDR +
930	                           sizeof(*tx_ring));
931	
932	      flags = enter_critical_section();
933	      written = sf32lb52_bt_ring_write(tx_ring, data + offset, chunk);
934	      leave_critical_section(flags);
935	
936	      if (written == 0)
937	        {
938	          if (HAL_GetTick() != start_time)
939	            {
940	              tick_count++;
941	              start_time = HAL_GetTick();
942	            }
943	
944	          if (tick_count >= 10)
945	            {
946	              syslog(LOG_ERR,
947	                     "sf32lb52 bt tx timeout: remaining=%lu\n",
948	                     (unsigned long)remaining);
949	              return -ETIMEDOUT;
950	            }
951	
952	          continue;
953	        }
954	
955	      offset += written;
956	      remaining -= written;
957	
958	      __DSB();
959	      wr_ptr = tx_ring->write_idx_mirror;
960	      sf32lb52_bt_trigger_tx();
961	      chunks++;
962	    }
963	
964	#if SF32LB52_BT_TRACE
965	  syslog(LOG_INFO,
966	         "sf32lb52 bt tx publish: total=%u chunks=%lu wr=%08lx first=%02x\n",
967	         len,
968	         (unsigned long)chunks,
969	         (unsigned long)wr_ptr,
970	         data[0]);
971	
972	  sf32lb52_bt_log_tx_state(tx_ring, "queued", wr_ptr);
973	#endif
974	
975	  if (data[0] == SF32LB52_BT_H4_CMD)
976	    {
977	      ret = sf32lb52_bt_wait_tx_idle(tx_ring);
978	      if (ret < 0)
979	        {
980	          return ret;
981	        }
982	    }
983	
984	  return OK;
985	}
 90	  uint32_t wdt_staus = 0xFF;
 91	  uint32_t wdt_time = 10;
 92	  uint16_t wdt_clk = 32768;
 93	
 94	  if (HAL_LXT_DISABLED())
 95	    {
 96	      is_lcpu_rccal = 1;
 97	    }
 98	
 99	  is_enable_lxt = 1 - is_lcpu_rccal;
100	  HAL_LCPU_CONFIG_set(HAL_LCPU_CONFIG_XTAL_ENABLED, &is_enable_lxt, 1);
101	  HAL_LCPU_CONFIG_set(HAL_LCPU_CONFIG_WDT_STATUS, &wdt_staus, 4);
102	  HAL_LCPU_CONFIG_set(HAL_LCPU_CONFIG_WDT_TIME, &wdt_time, 4);
103	  HAL_LCPU_CONFIG_set(HAL_LCPU_CONFIG_WDT_CLK_FEQ, &wdt_clk, 2);
104	  HAL_LCPU_CONFIG_set(HAL_LCPU_CONFIG_BT_RC_CAL_IN_L, &is_lcpu_rccal, 1);
105	
106	#if defined(SF32LB52X_REV_B) || defined(SF32LB52X_REV_AUTO)
107	  if (rev_id >= HAL_CHIP_REV_ID_A4)
108	    {
109	      uint32_t tx_queue = HCPU2LCPU_MB_CH1_BUF_START_ADDR;
110	      hal_lcpu_bluetooth_rom_config_t config = {0};
111	      hal_lcpu_ble_mem_config_t ble_config = {0};
112	
113	      config.bit_valid |= 1 << 10 | 1 << 6 | 1 << 2;
114	      config.lld_prog_delay = 3;
115	      config.is_fpga = 0;
116	      config.default_xtal_enabled = is_enable_lxt;
117	      HAL_LCPU_CONFIG_set(HAL_LCPU_CONFIG_HCPU_TX_QUEUE, &tx_queue, 4);
118	      HAL_LCPU_CONFIG_set(HAL_LCPU_CONFIG_BT_CONFIG, &config, sizeof(config));
119	
120	      ble_config.max_nb_of_hci_completed = 6;
121	      ble_config.bit_valid = 1 << 6;
122	      HAL_LCPU_CONFIG_set(HAL_LCPU_CONFIG_BT_KE_BUF,
123	                          &ble_config,
124	                          sizeof(ble_config));
125	    }
126	#else
127	  (void)rev_id;
128	#endif
129	}
