   409	                                       size_t offset)
   410	{
   411	  size_t remaining = len - offset;
   412	
   413	  if (offset == 0 && remaining > 1)
   414	    {
   415	      return 1;
   416	    }
   417	
   418	  return remaining;
   419	}
