   106	    //__asm("B .");
   107	    /* not switch back to XT48 if other clock source has been selected already */
   108	    if (RCC_SYSCLK_HRC48 == HAL_RCC_HCPU_GetClockSrc(RCC_CLK_MOD_SYS))
