   111	        HAL_HPAON_EnableXT48();
   112	        HAL_RCC_HCPU_ClockSelect(RCC_CLK_MOD_SYS, RCC_SYSCLK_HXT48);
   113	    }
   114	
   115	    HAL_RCC_HCPU_ClockSelect(RCC_CLK_MOD_HP_PERI, RCC_CLK_PERI_HXT48);
   116	
   117	    if (PM_STANDBY_BOOT != SystemPowerOnModeGet())
   118	    {
   119	        // Halt LCPU first to avoid LCPU in running state
   120	        HAL_HPAON_WakeCore(CORE_ID_LCPU);
   121	        HAL_RCC_Reset_and_Halt_LCPU(1);
   122	#ifndef USE_ATE_MODE
   123	        // get system configure from EFUSE
   124	        BSP_System_Config();
   125	#endif
   126	        HAL_HPAON_StartGTimer();
   127	        HAL_PMU_EnableRC32K(1);
   128	        HAL_PMU_LpCLockSelect(PMU_LPCLK_RC32);
   129	
