   135	        {
   136	            // RTC/GTIME/LPTIME Using same low power clock source
   137	            HAL_RTC_ENABLE_LXT();
   138	        }
   139	#endif
   140	
   141	#ifndef CFG_BOOTLOADER
   142	        {
