   144	        }
   145	
   146	#endif/* CFG_BOOTLOADER */
   147	        HAL_RCC_LCPU_ClockSelect(RCC_CLK_MOD_LP_PERI, RCC_CLK_PERI_HXT48);
   148	
   149	        HAL_HPAON_CANCEL_LP_ACTIVE_REQUEST();
   150	        if (HAL_LXT_DISABLED())
   151	            LRC_init();
   152	    }
   153	
   154	#ifndef USE_ATE_MODE
   155	    HAL_RCC_HCPU_ConfigHCLK(240);
   156	#else
   157	    HAL_RCC_HCPU_SetDiv(1, 1, 6);
   158	    HAL_RCC_HCPU_EnableDLL1(240000000); // only set freq here, pmu should changed by hardware directly
   159	    HAL_RCC_HCPU_ClockSelect(RCC_CLK_MOD_SYS, RCC_SYSCLK_DLL1);
