 233	static uint32_t sf32lb52_bt_ring_advance(uint32_t ptr, size_t len,
 234	                                         uint32_t buffer_size)
 235	{
 236	  uint32_t idx = CB_GET_PTR_IDX(ptr);
 237	  uint32_t mirror = CB_GET_PTR_MIRROR(ptr);
 238	
 239	  idx += len;
 240	  if (idx >= buffer_size)
 241	    {
 242	      idx -= buffer_size;
 243	      mirror = ~mirror;
 244	    }
 245	
 246	  return CB_MAKE_PTR_IDX_MIRROR(idx, mirror);
 247	}
