 249	static size_t sf32lb52_bt_ring_copy(uint8_t *dst,
 250	                                    const struct circular_buf *rx_ring,
 251	                                    uint32_t rd_ptr,
 252	                                    size_t len)
 253	{
 254	  const uint8_t *pool = (const uint8_t *)(rx_ring + 1);
 255	  uint32_t rd_idx = CB_GET_PTR_IDX(rd_ptr);
 256	  size_t tail;
 257	
 258	  if (len == 0)
 259	    {
 260	      return 0;
 261	    }
 262	
 263	  tail = rx_ring->buffer_size - rd_idx;
 264	  if (tail >= len)
 265	    {
 266	      memcpy(dst, &pool[rd_idx], len);
 267	      return len;
 268	    }
 269	
 270	  memcpy(dst, &pool[rd_idx], tail);
 271	  memcpy(&dst[tail], pool, len - tail);
 272	  return len;
 273	}
