 554	static int32_t sf32lb52_bt_rx_ind(ipc_queue_handle_t handle, size_t size)
 555	{
 556	  struct sf32lb52_bt_env_s *env = &g_sf32lb52_bt_env;
 557	  irqstate_t flags;
 558	  bool queue_work;
 559	
 560	  if (handle != env->ipc_port)
 561	    {
 562	      return -EINVAL;
 563	    }
 564	
 565	  if (!env->queue_open)
 566	    {
 567	      struct circular_buf *rx_ring = (struct circular_buf *)SF32LB52_BT_RX_BUF_ADDR;
 568	      #if SF32LB52_BT_TRACE
 569	            syslog(LOG_INFO, "sf32lb52 rx_ind (pre-open) wr=%08lx rd=%08lx\n",
 570	              (unsigned long)rx_ring->write_idx_mirror,
 571	              (unsigned long)rx_ring->read_idx_mirror);
 572	      #endif
 573	      return OK;
 574	    }
 575	
 576	  flags = enter_critical_section();
 577	  env->rx_work_pending = true;
 578	  queue_work = !env->rx_worker_running && work_available(&env->rx_work);
 579	  if (queue_work)
 580	    {
 581	      env->rx_worker_running = true;
 582	    }
 583	  leave_critical_section(flags);
 584	
 585	#if SF32LB52_BT_TRACE
 586	  {
 587	    struct circular_buf *rx_ring =
 588	        (struct circular_buf *)SF32LB52_BT_RX_BUF_ADDR;
 589	
 590	    up_invalidate_dcache((uintptr_t)SF32LB52_BT_RX_BUF_ADDR,
 591	                         (uintptr_t)SF32LB52_BT_RX_BUF_ADDR +
 592	                         sizeof(*rx_ring));
 593	
 594	    syslog(LOG_INFO,
 595	           "sf32lb52 rx_ind: size=%lu local=%08lx rd=%08lx wr=%08lx\n",
 596	           (unsigned long)size,
 597	           (unsigned long)env->rx_read_idx_mirror,
 598	           (unsigned long)rx_ring->read_idx_mirror,
 599	           (unsigned long)rx_ring->write_idx_mirror);
 600	  }
 601	#endif
 602	
 603	  if (queue_work)
 604	    {
 605	      int ret;
 606	
 607	      ret = work_queue(HPWORK, &env->rx_work, sf32lb52_bt_rx_worker,
 608	                       env, 0);
 609	      if (ret < 0)
 610	        {
 611	          flags = enter_critical_section();
 612	          env->rx_worker_running = false;
 613	          leave_critical_section(flags);
 614	
 615	          syslog(LOG_ERR, "sf32lb52 bt queue rx work failed: %d\n", ret);
