 885	int sf32lb52_host_send_packet(const uint8_t *data, uint16_t len)
 886	{
 887	  struct circular_buf *tx_ring =
 888	      (struct circular_buf *)SF32LB52_BT_TX_BUF_ADDR;
 889	  uint32_t start_time;
 890	  uint32_t tick_count;
 891	  size_t written;
 892	  size_t remaining;
 893	  size_t offset;
 894	  size_t chunk;
 895	  size_t chunks;
 896	  uint32_t wr_ptr;
 897	  int ret;
 898	
 899	  if (data == NULL || len == 0)
 900	    {
 901	      return -EINVAL;
 902	    }
 903	
 904	  if (g_sf32lb52_bt_status != SF32LB52_BT_STATUS_ENABLED ||
 905	      !g_sf32lb52_bt_env.queue_open)
 906	    {
 907	      return -ENODEV;
 908	    }
 909	
 910	  offset = 0;
 911	  remaining = len;
 912	  start_time = HAL_GetTick();
 913	  tick_count = 0;
 914	  chunks = 0;
 915	  wr_ptr = 0;
 916	
 917	  ret = sf32lb52_bt_wait_tx_idle(tx_ring);
 918	  if (ret < 0)
 919	    {
 920	      return ret;
 921	    }
 922	
 923	  while (remaining > 0)
 924	    {
 925	      irqstate_t flags;
 926	
 927	      chunk = sf32lb52_bt_tx_chunk_len(data, len, offset);
 928	
 929	      up_invalidate_dcache((uintptr_t)SF32LB52_BT_TX_BUF_ADDR,
 930	                           (uintptr_t)SF32LB52_BT_TX_BUF_ADDR +
 931	                           sizeof(*tx_ring));
 932	
 933	      flags = enter_critical_section();
 934	      written = sf32lb52_bt_ring_write(tx_ring, data + offset, chunk);
 935	      leave_critical_section(flags);
 936	
 937	      if (written == 0)
 938	        {
 939	          if (HAL_GetTick() != start_time)
 940	            {
 941	              tick_count++;
 942	              start_time = HAL_GetTick();
 943	            }
 944	
 945	          if (tick_count >= 10)
 946	            {
 947	              syslog(LOG_ERR,
 948	                     "sf32lb52 bt tx timeout: remaining=%lu\n",
 949	                     (unsigned long)remaining);
 950	              return -ETIMEDOUT;
 951	            }
 952	
 953	          continue;
 954	        }
 955	
 956	      offset += written;
 957	      remaining -= written;
 958	
 959	      __DSB();
 960	      wr_ptr = tx_ring->write_idx_mirror;
 961	      sf32lb52_bt_trigger_tx();
 962	      chunks++;
 963	    }
 964	
 965	#if SF32LB52_BT_TRACE
 966	  syslog(LOG_INFO,
 967	         "sf32lb52 bt tx publish: total=%u chunks=%lu wr=%08lx first=%02x\n",
 968	         len,
 969	         (unsigned long)chunks,
 970	         (unsigned long)wr_ptr,
 971	         data[0]);
 972	
 973	  sf32lb52_bt_log_tx_state(tx_ring, "queued", wr_ptr);
 974	#endif
 975	
 976	  if (data[0] == SF32LB52_BT_H4_CMD)
 977	    {
 978	      ret = sf32lb52_bt_wait_tx_idle(tx_ring);
 979	      if (ret < 0)
 980	        {
 981	          return ret;
 982	        }
 983	    }
 984	
 985	  return OK;
