 201	#if SF32LB52_BT_TRACE_ATT
 202	static void sf32lb52_bt_trace_att(const char *direction,
 203	                                  const uint8_t *data, size_t len)
 204	{
 205	  const size_t att_offset = H4_HEADER_SIZE +
 206	                            sizeof(struct bt_hci_acl_hdr_s) + 4;
 207	  uint16_t handle_flags;
 208	  uint16_t acl_len;
 209	  uint16_t l2cap_len;
 210	  uint16_t cid;
 211	  size_t att_len;
 212	
 213	  if (len <= att_offset || data[0] != H4_ACL)
 214	    {
 215	      return;
 216	    }
 217	
 218	  handle_flags = sf32lb52_bt_get_le16(&data[H4_HEADER_SIZE]);
 219	  if (((handle_flags >> 12) & 0x3) == 0x1)
 220	    {
 221	      return;
 222	    }
 223	
 224	  acl_len = sf32lb52_bt_get_le16(&data[H4_HEADER_SIZE + 2]);
 225	  if (acl_len < 5)
 226	    {
 227	      return;
 228	    }
 229	
 230	  l2cap_len = sf32lb52_bt_get_le16(
 231	    &data[H4_HEADER_SIZE + sizeof(struct bt_hci_acl_hdr_s)]);
 232	  cid = sf32lb52_bt_get_le16(
 233	    &data[H4_HEADER_SIZE + sizeof(struct bt_hci_acl_hdr_s) + 2]);
 234	  if (cid != 0x0004)
 235	    {
 236	      return;
 237	    }
 238	
 239	  att_len = acl_len - 4;
 240	  if (att_len > l2cap_len)
 241	    {
 242	      att_len = l2cap_len;
 243	    }
 244	
 245	  if (att_len > len - att_offset)
 246	    {
 247	      att_len = len - att_offset;
 248	    }
 249	
 250	  if (att_len == 0)
 251	    {
 252	      return;
 253	    }
 254	
 255	  syslog(LOG_INFO,
 256	         "sf32lb52 bth4 ATT %s: opcode=0x%02x h4_len=%lu att_len=%lu "
 257	         "data=%02x %02x %02x %02x %02x %02x %02x %02x\n",
 258	         direction, data[att_offset], (unsigned long)len,
 259	         (unsigned long)att_len,
 260	         data[att_offset],
 261	         att_len > 1 ? data[att_offset + 1] : 0,
 262	         att_len > 2 ? data[att_offset + 2] : 0,
 263	         att_len > 3 ? data[att_offset + 3] : 0,
 264	         att_len > 4 ? data[att_offset + 4] : 0,
 265	         att_len > 5 ? data[att_offset + 5] : 0,
 266	         att_len > 6 ? data[att_offset + 6] : 0,
 267	         att_len > 7 ? data[att_offset + 7] : 0);
