 277	static ssize_t sf32lb52_bt_h4_packet_len(const uint8_t *data, size_t len)
 278	{
 279	  uint16_t payload_len;
 280	
 281	  if (len < H4_HEADER_SIZE)
 282	    {
 283	      return 0;
 284	    }
 285	
 286	  switch (data[0])
 287	    {
 288	      case H4_EVT:
 289	        if (len < H4_HEADER_SIZE + sizeof(struct bt_hci_evt_hdr_s))
 290	          {
 291	            return 0;
 292	          }
 293	
 294	        payload_len = data[H4_HEADER_SIZE + 1];
 295	        return H4_HEADER_SIZE + sizeof(struct bt_hci_evt_hdr_s) + payload_len;
 296	
 297	      case H4_ACL:
 298	        if (len < H4_HEADER_SIZE + sizeof(struct bt_hci_acl_hdr_s))
 299	          {
 300	            return 0;
 301	          }
 302	
 303	        payload_len = sf32lb52_bt_get_le16(&data[H4_HEADER_SIZE + 2]);
 304	        return H4_HEADER_SIZE + sizeof(struct bt_hci_acl_hdr_s) + payload_len;
 305	
 306	      case H4_ISO:
 307	        if (len < H4_HEADER_SIZE + sizeof(struct bt_hci_iso_hdr_s))
 308	          {
 309	            return 0;
 310	          }
 311	
 312	        payload_len = sf32lb52_bt_get_le16(&data[H4_HEADER_SIZE + 2]) & 0x3fff;
 313	        return H4_HEADER_SIZE + sizeof(struct bt_hci_iso_hdr_s) + payload_len;
 314	
 315	      default:
 316	        return -EINVAL;
 317	    }
 318	}
