 205	static size_t sf32lb52_bt_ring_data_len(uint32_t rd_ptr, uint32_t wr_ptr,
 206	                                        uint32_t buffer_size)
 207	{
 208	  uint32_t rd_idx = CB_GET_PTR_IDX(rd_ptr);
 209	  uint32_t wr_idx = CB_GET_PTR_IDX(wr_ptr);
 210	  uint32_t rd_mirror = CB_GET_PTR_MIRROR(rd_ptr);
 211	  uint32_t wr_mirror = CB_GET_PTR_MIRROR(wr_ptr);
 212	
 213	  if (rd_idx == wr_idx)
 214	    {
 215	      return rd_mirror == wr_mirror ? 0 : buffer_size;
 216	    }
 217	
 218	  if (wr_idx > rd_idx)
 219	    {
 220	      return wr_idx - rd_idx;
 221	    }
 222	
 223	  return buffer_size - (rd_idx - wr_idx);
 224	}
 225	
 226	static size_t sf32lb52_bt_ring_space_len(uint32_t rd_ptr, uint32_t wr_ptr,
 227	                                         uint32_t buffer_size)
 228	{
 229	  return buffer_size - sf32lb52_bt_ring_data_len(rd_ptr, wr_ptr,
 230	                                                buffer_size);
 231	}
 232	
 233	static uint32_t sf32lb52_bt_ring_advance(uint32_t ptr, size_t len,
 234	                                         uint32_t buffer_size)
 235	{
 236	  uint32_t idx = CB_GET_PTR_IDX(ptr);
 237	  uint32_t mirror = CB_GET_PTR_MIRROR(ptr);
 238	
 239	  idx += len;
 240	  if (idx >= buffer_size)
 241	    {
 242	      idx -= buffer_size;
 243	      mirror = ~mirror;
 244	    }
 245	
 246	  return CB_MAKE_PTR_IDX_MIRROR(idx, mirror);
 247	}
 248	
 249	static size_t sf32lb52_bt_ring_copy(uint8_t *dst,
 250	                                    const struct circular_buf *rx_ring,
 251	                                    uint32_t rd_ptr,
 252	                                    size_t len)
 253	{
 254	  const uint8_t *pool = (const uint8_t *)(rx_ring + 1);
 255	  uint32_t rd_idx = CB_GET_PTR_IDX(rd_ptr);
 256	  size_t tail;
 257	
 258	  if (len == 0)
 259	    {
 260	      return 0;
 261	    }
 262	
 263	  tail = rx_ring->buffer_size - rd_idx;
 264	  if (tail >= len)
 265	    {
 266	      memcpy(dst, &pool[rd_idx], len);
 267	      return len;
 268	    }
 269	
 270	  memcpy(dst, &pool[rd_idx], tail);
 271	  memcpy(&dst[tail], pool, len - tail);
 272	  return len;
 273	}
 274	
 275	static size_t sf32lb52_bt_ring_write(struct circular_buf *tx_ring,
 276	                                     const uint8_t *src, size_t len)
 277	{
 278	  uint8_t *pool = (uint8_t *)(tx_ring + 1);
 279	  uint32_t wr_ptr = tx_ring->write_idx_mirror;
 280	  uint32_t wr_idx = CB_GET_PTR_IDX(wr_ptr);
 281	  size_t space;
 282	  size_t tail;
 283	
 284	  space = sf32lb52_bt_ring_space_len(tx_ring->read_idx_mirror,
 285	                                     wr_ptr,
 286	                                     tx_ring->buffer_size);
 287	  if (space == 0)
 288	    {
 289	      return 0;
 290	    }
 291	
 292	  if (len > space)
 293	    {
 294	      len = space;
 295	    }
 296	
 297	  tail = tx_ring->buffer_size - wr_idx;
 298	  if (tail >= len)
 299	    {
 300	      memcpy(&pool[wr_idx], src, len);
 301	      up_clean_dcache((uintptr_t)&pool[wr_idx],
 302	                      (uintptr_t)&pool[wr_idx] + len);
 303	    }
 304	  else
 305	    {
 306	      memcpy(&pool[wr_idx], src, tail);
 307	      memcpy(pool, &src[tail], len - tail);
 308	      up_clean_dcache((uintptr_t)&pool[wr_idx],
 309	                      (uintptr_t)&pool[wr_idx] + tail);
 310	      up_clean_dcache((uintptr_t)pool,
 311	                      (uintptr_t)pool + len - tail);
 312	    }
 313	
 314	  tx_ring->write_idx_mirror = sf32lb52_bt_ring_advance(wr_ptr, len,
 315	                                                       tx_ring->buffer_size);
 316	  up_clean_dcache((uintptr_t)tx_ring,
 317	                  (uintptr_t)tx_ring + sizeof(*tx_ring));
 318	  __DSB();
 319	
 320	  return len;
 321	}
 322	
 323	static size_t sf32lb52_bt_tx_pending(struct circular_buf *tx_ring,
 324	                                     uint32_t *rd_ptr,
 325	                                     uint32_t *wr_ptr)
 326	{
 327	  uint32_t rd;
 328	  uint32_t wr;
 329	
 330	  up_invalidate_dcache((uintptr_t)SF32LB52_BT_TX_BUF_ADDR,
 331	                       (uintptr_t)SF32LB52_BT_TX_BUF_ADDR +
 332	                       sizeof(*tx_ring));
 333	
 334	  rd = tx_ring->read_idx_mirror;
 335	  wr = tx_ring->write_idx_mirror;
 336	
 337	  if (rd_ptr != NULL)
 338	    {
 339	      *rd_ptr = rd;
 340	    }
 341	
 342	  if (wr_ptr != NULL)
 343	    {
 344	      *wr_ptr = wr;
 345	    }
 346	
 347	  return sf32lb52_bt_ring_data_len(rd, wr, tx_ring->buffer_size);
 348	}
