 723	int sf32lb52_bt_controller_enable(void)
 724	{
 725	  int ret;
 726	
 727	  if (g_sf32lb52_bt_status == SF32LB52_BT_STATUS_ENABLED)
 728	    {
 729	      return OK;
 730	    }
 731	
 732	  if (g_sf32lb52_bt_status != SF32LB52_BT_STATUS_INITED)
 733	    {
 734	      return -EPERM;
 735	    }
 736	
 737	  sf32lb52_bt_prepare_stack_nvds();
 738	  HAL_LCPU_ASSERT_INFO_clear();
 739	
 740	  ret = lcpu_power_on();
 741	  if (ret != 0)
 742	    {
 743	      return -EIO;
 744	    }
 745	
 746	  /* The L2H_MAILBOX (0x40002000) is on the LPSYS APB bus.  Its CxIER
 747	   * register is only writable when the LPSYS bus bridge is active.
 748	   * Wake the LCPU first so the bus bridge is powered, THEN open the
 749	   * IPC queue (which writes CxIER to unmask the mailbox RX interrupt).
 750	   * The SDK reference ipc_hw_enable_interrupt2() has the same
 751	   * HAL_HPAON_WakeCore() before the UNMASK call.
 752	   */
 753	
 754	  HAL_HPAON_WakeCore(CORE_ID_LCPU);
 755	  g_sf32lb52_bt_env.wake_held = true;
 756	
 757	  usleep(500000);
 758	
 759	  ret = ipc_queue_open(g_sf32lb52_bt_env.ipc_port);
 760	  if (ret < 0)
 761	    {
 762	      HAL_HPAON_CANCEL_LP_ACTIVE_REQUEST();
 763	      g_sf32lb52_bt_env.wake_held = false;
 764	      return ret;
 765	    }
 766	
 767	  /* Flush H2L TX ring to SRAM immediately after ipc_queue_open so
 768	   * LCPU sees the reset indices (read_idx=write_idx=0) before it
 769	   * tries to process any stale data from a previous session.
 770	   */
 771	  up_clean_dcache((uintptr_t)SF32LB52_BT_TX_BUF_ADDR,
 772	                  (uintptr_t)SF32LB52_BT_TX_BUF_ADDR +
 773	                  SF32LB52_BT_TX_BUF_SIZE);
 774	  __DSB();
 775	
 776	  /* After every lcpu_power_on(), LCPU resets its TX ring write pointer
 777	   * (write_idx_mirror) to 0 and writes its own boot responses into the
 778	   * ring.  HCPU's read pointer (read_idx_mirror) may still hold the
 779	   * non-zero value from the previous session -- dirty in DCache or
 780	   * stored in SRAM.  If we do not synchronise them:
 781	   *
 782	   *   circular_buf_data_len() = wrap(write_idx - read_idx)
 783	   *
 784	   * returns a large garbage value, and LCPU's fresh boot events
 785	   * plus ring garbage all replay as "new" HCI responses.  These
 786	   * ghost events are consumed by the host as replies to real commands,
 787	   * so HCI_Reset (0x0c01) is never actually executed by the controller,
 788	   * and bt_le_adv_start later gets "Command Disallowed" (0x07).
 789	   *
 790	   * Fix: flush DCache to write back any dirty read_idx and to load
 791	   * LCPU's current write_idx from SRAM, then advance read_idx to
 792	   * write_idx (discard ALL pending LCPU boot data), then clean the
 793	   * DCache so LCPU sees the updated read pointer in SRAM.
 794	   */
 795	
 796	  {
 797	    struct circular_buf *rx_ring =
 798	        (struct circular_buf *)SF32LB52_BT_RX_BUF_ADDR;
 799	
 800	    ret = sf32lb52_bt_wait_rx_ring_ready();
 801	    if (ret < 0)
 802	      {
 803	        syslog(LOG_ERR, "sf32lb52 rx ring not ready: %d\n", ret);
 804	        ipc_queue_close(g_sf32lb52_bt_env.ipc_port);
 805	        HAL_HPAON_CANCEL_LP_ACTIVE_REQUEST();
 806	        g_sf32lb52_bt_env.wake_held = false;
 807	        return ret;
 808	      }
 809	
 810	    rx_ring->read_idx_mirror = rx_ring->write_idx_mirror;
 811	    g_sf32lb52_bt_env.rx_read_idx_mirror = rx_ring->write_idx_mirror;
 812	
 813	    up_clean_dcache((uintptr_t)SF32LB52_BT_RX_BUF_ADDR,
 814	                    (uintptr_t)SF32LB52_BT_RX_BUF_ADDR +
 815	                    sizeof(*rx_ring));
 816	    __DSB();
 817	  }
 818	
 819	  {
 820	    volatile MAILBOX_CH_TypeDef *l2h = L2H_MAILBOX;
 821	    uint32_t nvic_bit = (1UL << (LCPU2HCPU_IRQn & 0x1F));
 822	    uint32_t nvic_en  = NVIC->ISER[LCPU2HCPU_IRQn >> 5];
 823	
 824	    (void)l2h;
 825	    (void)nvic_bit;
 826	    (void)nvic_en;
 827	  }
 828	
 829	  g_sf32lb52_bt_env.queue_open = true;
 830	  g_sf32lb52_bt_status = SF32LB52_BT_STATUS_ENABLED;
 831	
 832	  return OK;
 833	}
