 835	int sf32lb52_bt_controller_disable(void)
 836	{
 837	  int ret = OK;
 838	  int tmpret;
 839	  bool queue_open;
 840	
 841	  if (g_sf32lb52_bt_status != SF32LB52_BT_STATUS_ENABLED)
 842	    {
 843	      return -EPERM;
 844	    }
 845	
 846	  queue_open = g_sf32lb52_bt_env.queue_open;
 847	  g_sf32lb52_bt_env.queue_open = false;
 848	  g_sf32lb52_bt_env.rx_work_pending = false;
 849	  g_sf32lb52_bt_env.rx_worker_running = false;
 850	  if (!work_available(&g_sf32lb52_bt_env.rx_work))
 851	    {
 852	      tmpret = work_cancel_sync(HPWORK, &g_sf32lb52_bt_env.rx_work);
 853	      if (tmpret < 0 && tmpret != -ENOENT && ret == OK)
 854	        {
 855	          ret = tmpret;
 856	        }
 857	    }
 858	
 859	  if (queue_open)
 860	    {
 861	      tmpret = ipc_queue_close(g_sf32lb52_bt_env.ipc_port);
 862	      if (tmpret < 0 && ret == OK)
 863	        {
 864	          ret = tmpret;
 865	        }
 866	    }
 867	
 868	  if (g_sf32lb52_bt_env.wake_held)
 869	    {
 870	      HAL_HPAON_CANCEL_LP_ACTIVE_REQUEST();
 871	      g_sf32lb52_bt_env.wake_held = false;
 872	    }
 873	
 874	  tmpret = lcpu_power_off();
 875	  if (tmpret != 0 && ret == OK)
 876	    {
 877	      ret = -EIO;
 878	    }
 879	
 880	  g_sf32lb52_bt_env.notify_host = NULL;
 881	  g_sf32lb52_bt_status = SF32LB52_BT_STATUS_INITED;
 882	  return ret;
 883	}
