   356	static int sf32lb52_bt_wait_tx_idle(struct circular_buf *tx_ring)
   357	{
   358	  uint32_t start_time = HAL_GetTick();
   359	  uint32_t tick_count = 0;
   360	  uint32_t rd_ptr = 0;
   361	  uint32_t wr_ptr = 0;
   362	
   363	  while (sf32lb52_bt_tx_pending(tx_ring, &rd_ptr, &wr_ptr) > 0)
   364	    {
   365	      sf32lb52_bt_trigger_tx();
   366	
   367	      if (HAL_GetTick() != start_time)
   368	        {
   369	          tick_count++;
   370	          start_time = HAL_GetTick();
   371	        }
   372	
   373	      if (tick_count >= 100)
   374	        {
   375	          syslog(LOG_ERR,
   376	                 "sf32lb52 bt tx busy: rd=%08lx wr=%08lx\n",
   377	                 (unsigned long)rd_ptr,
   378	                 (unsigned long)wr_ptr);
   379	          return -ETIMEDOUT;
   380	        }
   381	
   382	      usleep(1000);
   383	    }
   384	
   385	  return OK;
