   422	static void sf32lb52_bt_rx_worker(FAR void *arg)
   423	{
   424	  struct sf32lb52_bt_env_s *env = arg;
   425	
   426	  for (;;)
   427	    {
   428	      irqstate_t flags;
   429	      int empty_retries = 0;
   430	
   431	      for (;;)
   432	        {
   433	          size_t size;
   434	          size_t read_len;
   435	          int ret;
   436	          struct circular_buf *rx_ring;
   437	          uint32_t wr_ptr;
   438	
   439	          flags = enter_critical_section();
   440	
   441	          if (!env->queue_open || env->ipc_port == IPC_QUEUE_INVALID_HANDLE)
   442	            {
   443	              env->rx_work_pending = false;
   444	              env->rx_worker_running = false;
   445	              leave_critical_section(flags);
   446	              return;
   447	            }
   448	
   449	          leave_critical_section(flags);
   450	
   451	          up_invalidate_dcache((uintptr_t)SF32LB52_BT_RX_BUF_ADDR,
   452	                               (uintptr_t)SF32LB52_BT_RX_BUF_ADDR +
   453	                               SF32LB52_BT_RX_BUF_SIZE);
   454	
   455	          flags = enter_critical_section();
   456	
   457	          if (!env->queue_open || env->ipc_port == IPC_QUEUE_INVALID_HANDLE)
   458	            {
   459	              env->rx_work_pending = false;
   460	              env->rx_worker_running = false;
   461	              leave_critical_section(flags);
   462	              return;
   463	            }
   464	
   465	          rx_ring = (struct circular_buf *)SF32LB52_BT_RX_BUF_ADDR;
   466	          wr_ptr = rx_ring->write_idx_mirror;
   467	          size = sf32lb52_bt_ring_data_len(env->rx_read_idx_mirror,
   468	                                          wr_ptr,
   469	                                          rx_ring->buffer_size);
   470	          if (size == 0)
   471	            {
   472	              uint32_t rd_ptr = rx_ring->read_idx_mirror;
   473	              uint32_t local_rd = env->rx_read_idx_mirror;
   474	
   475	              leave_critical_section(flags);
   476	
   477	              if (empty_retries++ < 20)
   478	                {
   479	                  usleep(1000);
   480	                  continue;
   481	                }
   482	
   483	          #if SF32LB52_BT_TRACE
   484	              syslog(LOG_INFO,
   485	                "sf32lb52 bt rx empty: local=%08lx rd=%08lx wr=%08lx\n",
   486	                (unsigned long)local_rd,
   487	                (unsigned long)rd_ptr,
   488	                (unsigned long)wr_ptr);
   489	          #endif
   490	              break;
   491	            }
   492	
   493	          empty_retries = 0;
   494	
   495	          if (size > sizeof(env->data_buf))
   496	            {
   497	              size = sizeof(env->data_buf);
   498	            }
   499	
   500	          read_len = sf32lb52_bt_ring_copy(env->data_buf, rx_ring,
   501	                                           env->rx_read_idx_mirror, size);
   502	          if (read_len == 0)
   503	            {
   504	              leave_critical_section(flags);
   505	              break;
   506	            }
   507	
   508	          env->rx_read_idx_mirror = sf32lb52_bt_ring_advance(
   509	              env->rx_read_idx_mirror, read_len, rx_ring->buffer_size);
   510	          rx_ring->read_idx_mirror = env->rx_read_idx_mirror;
   511	          __DSB();
   512	
   513	          up_clean_dcache((uintptr_t)SF32LB52_BT_RX_BUF_ADDR,
   514	                          (uintptr_t)SF32LB52_BT_RX_BUF_ADDR +
   515	                          sizeof(*rx_ring));
   516	
   517	          env->rx_count++;
   518	
   519	          leave_critical_section(flags);
   520	
   521	        #if SF32LB52_BT_TRACE
   522	             syslog(LOG_INFO,
   523	               "sf32lb52 bt rx drain: len=%lu local=%08lx wr=%08lx\n",
   524	               (unsigned long)read_len,
   525	               (unsigned long)env->rx_read_idx_mirror,
   526	               (unsigned long)wr_ptr);
   527	        #endif
   528	
   529	          if (env->notify_host == NULL)
   530	            {
   531	              continue;
   532	            }
   533	
   534	          ret = env->notify_host(env->data_buf, read_len);
   535	          if (ret < 0)
   536	            {
   537	              syslog(LOG_ERR, "sf32lb52 bt rx callback: %d\n", ret);
   538	            }
   539	        }
   540	
   541	      flags = enter_critical_section();
   542	      if (!env->rx_work_pending)
   543	        {
   544	          env->rx_worker_running = false;
   545	          leave_critical_section(flags);
   546	          break;
   547	        }
   548	
   549	      env->rx_work_pending = false;
   550	      leave_critical_section(flags);
   551	    }
   552	}
