   275	static size_t sf32lb52_bt_ring_write(struct circular_buf *tx_ring,
   276	                                     const uint8_t *src, size_t len)
   277	{
   278	  uint8_t *pool = (uint8_t *)(tx_ring + 1);
   279	  uint32_t wr_ptr = tx_ring->write_idx_mirror;
   280	  uint32_t wr_idx = CB_GET_PTR_IDX(wr_ptr);
   281	  size_t space;
   282	  size_t tail;
   283	
   284	  space = sf32lb52_bt_ring_space_len(tx_ring->read_idx_mirror,
   285	                                     wr_ptr,
   286	                                     tx_ring->buffer_size);
   287	  if (space == 0)
   288	    {
   289	      return 0;
   290	    }
   291	
   292	  if (len > space)
   293	    {
   294	      len = space;
   295	    }
   296	
   297	  tail = tx_ring->buffer_size - wr_idx;
   298	  if (tail >= len)
   299	    {
   300	      memcpy(&pool[wr_idx], src, len);
   301	      up_clean_dcache((uintptr_t)&pool[wr_idx],
   302	                      (uintptr_t)&pool[wr_idx] + len);
   303	    }
   304	  else
   305	    {
   306	      memcpy(&pool[wr_idx], src, tail);
   307	      memcpy(pool, &src[tail], len - tail);
   308	      up_clean_dcache((uintptr_t)&pool[wr_idx],
   309	                      (uintptr_t)&pool[wr_idx] + tail);
   310	      up_clean_dcache((uintptr_t)pool,
   311	                      (uintptr_t)pool + len - tail);
   312	    }
   313	
   314	  tx_ring->write_idx_mirror = sf32lb52_bt_ring_advance(wr_ptr, len,
   315	                                                       tx_ring->buffer_size);
   316	  up_clean_dcache((uintptr_t)tx_ring,
   317	                  (uintptr_t)tx_ring + sizeof(*tx_ring));
   318	  __DSB();
   319	
   320	  return len;
   321	}
