  4392	static void rx_work_handler(struct k_work *work)
  4393	{
  4394		int err;
  4395		struct net_buf *buf;
  4396		struct bt_dev *hdev = CONTAINER_OF(work, struct bt_dev, rx_work);
  4397	
  4398		LOG_DBG("dev:%d, Getting net_buf from queue", hdev->dev_id);
  4399		buf = net_buf_slist_get(&hdev->rx_queue);
  4400		if (!buf) {
  4401			return;
  4402		}
  4403	
  4404		LOG_DBG("buf %p type %u len %u", buf, bt_buf_get_type(buf), buf->len);
  4405	
  4406		switch (bt_buf_get_type(buf)) {
  4407	#if defined(CONFIG_BT_CONN)
  4408		case BT_BUF_ACL_IN:
  4409			hci_acl(hdev, buf);
  4410			break;
  4411	#endif /* CONFIG_BT_CONN */
  4412	#if defined(CONFIG_BT_ISO)
  4413		case BT_BUF_ISO_IN:
  4414			hci_iso(hdev, buf);
  4415			break;
  4416	#endif /* CONFIG_BT_ISO */
  4417		case BT_BUF_EVT:
  4418			hci_event(hdev, buf);
  4419			break;
  4420		default:
  4421			LOG_ERR("Unknown buf type %u", bt_buf_get_type(buf));
  4422			net_buf_unref(buf);
  4423			break;
  4424		}
