 151	  long buf_size = rx_ring->buffer_size;
 152	
 153	  if (!sf32lb52_bt_rx_ring_valid(rx_ring))
 154	    {
 155	      syslog(LOG_WARNING,
 156	             "%s rx ring invalid: buf=%ld expected=%lu rd=%08lx wr=%08lx\n",
