 418	static uint32_t sf32lb52_bt_ring_advance(uint32_t ptr, size_t len,
 419	                                         uint32_t buffer_size)
 420	{
 421	  uint32_t idx = CB_GET_PTR_IDX(ptr);
 422	  uint32_t mirror = CB_GET_PTR_MIRROR(ptr);
 423	
 424	  idx += len;
 425	  if (idx >= buffer_size)
 426	    {
 427	      idx -= buffer_size;
 428	      mirror = ~mirror;
 429	    }
 430	
 431	  return CB_MAKE_PTR_IDX_MIRROR(idx, mirror);
 432	}
