 434	static size_t sf32lb52_bt_ring_copy(uint8_t *dst,
 435	                                    const struct circular_buf *rx_ring,
 436	                                    uint32_t rd_ptr,
 437	                                    size_t len)
 438	{
 439	  const uint8_t *pool = (const uint8_t *)(rx_ring + 1);
 440	  uint32_t rd_idx = CB_GET_PTR_IDX(rd_ptr);
 441	  size_t tail;
 442	
 443	  if (len == 0)
 444	    {
 445	      return 0;
 446	    }
 447	
 448	  tail = rx_ring->buffer_size - rd_idx;
 449	  if (tail >= len)
 450	    {
 451	      memcpy(dst, &pool[rd_idx], len);
 452	      return len;
 453	    }
 454	
 455	  memcpy(dst, &pool[rd_idx], tail);
 456	  memcpy(&dst[tail], pool, len - tail);
 457	  return len;
 458	}
