  16	static inline enum circular_buf_state circular_buf_status(struct circular_buf *cb,
  17	                                                          uint32_t rd_ptr,
  18	                                                          uint32_t wr_ptr)
  19	{
  20	    uint32_t rd_idx = CB_GET_PTR_IDX(rd_ptr);
  21	    uint32_t wr_idx = CB_GET_PTR_IDX(wr_ptr);
  22	    uint32_t rd_mirror = CB_GET_PTR_MIRROR(rd_ptr);
  23	    uint32_t wr_mirror = CB_GET_PTR_MIRROR(wr_ptr);
  24	
  25	    if (rd_idx == wr_idx)
  26	    {
  27	        return rd_mirror == wr_mirror ? CIRCULAR_BUF_EMPTY : CIRCULAR_BUF_FULL;
  28	    }
  29	
  30	    return CIRCULAR_BUF_HALFFULL;
  31	}
