 358	__ROM_USED size_t circular_buf_data_len(struct circular_buf *cb)
 359	{
 360	    uint32_t rd_idx;
 361	    uint32_t wr_idx;
 362	    uint32_t rd_ptr = cb->read_idx_mirror;
 363	    uint32_t wr_ptr = cb->write_idx_mirror;
 364	
 365	    switch (circular_buf_status(cb, rd_ptr, wr_ptr))
 366	    {
 367	        case CIRCULAR_BUF_EMPTY:
 368	            return 0;
 369	
 370	        case CIRCULAR_BUF_FULL:
 371	            return cb->buffer_size;
 372	
 373	        case CIRCULAR_BUF_HALFFULL:
 374	        default:
 375	            rd_idx = CB_GET_PTR_IDX(rd_ptr);
 376	            wr_idx = CB_GET_PTR_IDX(wr_ptr);
 377	            if (wr_idx > rd_idx)
 378	            {
 379	                return wr_idx - rd_idx;
 380	            }
 381	
 382	            return cb->buffer_size - (rd_idx - wr_idx);
 383	    }
 384	}
