 398	
 399	    if (!ipc_ctx.init)
 400	    {
 401	        return true;
 402	    }
 403	
 404	    mask = os_interrupt_disable();
 405	    queue = &ipc_ctx.queues[0];
 406	    for (i = 0; i < IPC_LOGICAL_QUEUE_NUM; i++)
 407	    {
 408	        if (queue->active && (ipc_hw_check_interrupt(&queue->hw_q_handle) != 0))
 409	        {
 410	            is_idle = false;
 411	            break;
 412	        }
 413	
 414	        if (queue->active && queue->tx_ring_buffer &&
 415	            (circular_buf_data_len(queue->tx_ring_buffer) > 0))
 416	        {
 417	            is_idle = false;
 418	            break;
 419	        }
 420	
 421	        queue++;
 422	    }
 423	    os_interrupt_enable(mask);
 424	
 425	    return is_idle;
 426	}
