 607	static void sf32lb52_bt_rx_worker(FAR void *arg)
 608	{
 609	  struct sf32lb52_bt_env_s *env = arg;
 610	
 611	  for (;;)
 612	    {
 613	      irqstate_t flags;
 614	      int empty_retries = 0;
 615	
 616	      for (;;)
 617	        {
 618	          size_t size;
 619	          size_t read_len;
 620	          int ret;
 621	          struct circular_buf *rx_ring;
 622	          uint32_t wr_ptr;
 623	
 624	          flags = enter_critical_section();
 625	
 626	          if (!env->queue_open || env->ipc_port == IPC_QUEUE_INVALID_HANDLE)
 627	            {
 628	              env->rx_work_pending = false;
 629	              env->rx_worker_running = false;
 630	              leave_critical_section(flags);
 631	              return;
 632	            }
 633	
 634	          leave_critical_section(flags);
 635	
 636	          up_invalidate_dcache((uintptr_t)SF32LB52_BT_RX_BUF_ADDR,
 637	                               (uintptr_t)SF32LB52_BT_RX_BUF_ADDR +
 638	                               SF32LB52_BT_RX_BUF_SIZE);
 639	
 640	          flags = enter_critical_section();
 641	
 642	          if (!env->queue_open || env->ipc_port == IPC_QUEUE_INVALID_HANDLE)
 643	            {
 644	              env->rx_work_pending = false;
 645	              env->rx_worker_running = false;
 646	              leave_critical_section(flags);
 647	              return;
 648	            }
 649	
 650	          rx_ring = (struct circular_buf *)SF32LB52_BT_RX_BUF_ADDR;
 651	          wr_ptr = rx_ring->write_idx_mirror;
 652	          size = sf32lb52_bt_ring_data_len(env->rx_read_idx_mirror,
 653	                                          wr_ptr,
 654	                                          rx_ring->buffer_size);
 655	          if (size == 0)
 656	            {
 657	              uint32_t rd_ptr = rx_ring->read_idx_mirror;
 658	              uint32_t local_rd = env->rx_read_idx_mirror;
 659	
 660	              leave_critical_section(flags);
 661	
 662	              if (empty_retries++ < 20)
 663	                {
 664	                  usleep(1000);
 665	                  continue;
 666	                }
 667	
 668	          #if SF32LB52_BT_TRACE
 669	              syslog(LOG_INFO,
 670	                "sf32lb52 bt rx empty: local=%08lx rd=%08lx wr=%08lx\n",
 671	                (unsigned long)local_rd,
 672	                (unsigned long)rd_ptr,
 673	                (unsigned long)wr_ptr);
 674	          #endif
 675	              break;
 676	            }
 677	
 678	          empty_retries = 0;
 679	
 680	          if (size > sizeof(env->data_buf))
 681	            {
 682	              size = sizeof(env->data_buf);
 683	            }
 684	
 685	          read_len = sf32lb52_bt_ring_copy(env->data_buf, rx_ring,
 686	                                           env->rx_read_idx_mirror, size);
 687	          if (read_len == 0)
 688	            {
 689	              leave_critical_section(flags);
 690	              break;
 691	            }
 692	
 693	          env->rx_read_idx_mirror = sf32lb52_bt_ring_advance(
 694	              env->rx_read_idx_mirror, read_len, rx_ring->buffer_size);
 695	          rx_ring->read_idx_mirror = env->rx_read_idx_mirror;
 696	          __DSB();
 697	
 698	          up_clean_dcache((uintptr_t)SF32LB52_BT_RX_BUF_ADDR,
 699	                          (uintptr_t)SF32LB52_BT_RX_BUF_ADDR +
 700	                          sizeof(*rx_ring));
 701	
 702	          env->rx_count++;
 703	
 704	          leave_critical_section(flags);
 705	
 706	        #if SF32LB52_BT_TRACE
 707	             syslog(LOG_INFO,
 708	               "sf32lb52 bt rx drain: len=%lu local=%08lx wr=%08lx\n",
 709	               (unsigned long)read_len,
 710	               (unsigned long)env->rx_read_idx_mirror,
 711	               (unsigned long)wr_ptr);
 712	        #endif
 713	
 714	          if (env->notify_host == NULL)
 715	            {
 716	              continue;
 717	            }
 718	
 719	          sf32lb52_bt_diag_rx_feed(env->data_buf, read_len);
 720	          ret = env->notify_host(env->data_buf, read_len);
 721	          if (ret < 0)
 722	            {
 723	              syslog(LOG_ERR,
 724	                     "sf32lb52 bt rx deliver failed: ret=%d len=%u\n",
 725	                     ret, (unsigned int)read_len);
 726	            }
 727	        }
 728	
 729	      flags = enter_critical_section();
 730	      if (!env->rx_work_pending)
 731	        {
 732	          env->rx_worker_running = false;
 733	          leave_critical_section(flags);
 734	          break;
 735	        }
 736	
 737	      env->rx_work_pending = false;
 738	      leave_critical_section(flags);
 739	    }
 740	}
 741	
 742	static int32_t sf32lb52_bt_rx_ind(ipc_queue_handle_t handle, size_t size)
 743	{
 744	  struct sf32lb52_bt_env_s *env = &g_sf32lb52_bt_env;
 745	  irqstate_t flags;
 746	  bool queue_work;
 747	  bool work_ready;
 748	  bool report_exit_window = false;
 749	
 750	  if (handle != env->ipc_port)
 751	    {
 752	      return -EINVAL;
 753	    }
 754	
 755	  if (!env->queue_open)
 756	    {
 757	      struct circular_buf *rx_ring = (struct circular_buf *)SF32LB52_BT_RX_BUF_ADDR;
 758	      #if SF32LB52_BT_TRACE
 759	            syslog(LOG_INFO, "sf32lb52 rx_ind (pre-open) wr=%08lx rd=%08lx\n",
 760	              (unsigned long)rx_ring->write_idx_mirror,
 761	              (unsigned long)rx_ring->read_idx_mirror);
 762	      #endif
 763	      return OK;
 764	    }
 765	
 766	  flags = enter_critical_section();
 767	  env->rx_work_pending = true;
 768	  work_ready = work_available(&env->rx_work);
 769	  queue_work = !env->rx_worker_running && work_ready;
 770	  if (queue_work)
 771	    {
 772	      env->rx_worker_running = true;
 773	      env->rx_exit_window_reported = false;
 774	    }
 775	  else if (!env->rx_worker_running && !work_ready &&
 776	           !env->rx_exit_window_reported)
 777	    {
 778	      env->rx_exit_window_reported = true;
 779	      report_exit_window = true;
 780	    }
 781	  leave_critical_section(flags);
 782	
 783	  if (report_exit_window)
 784	    {
 785	      syslog(LOG_WARNING, "sf32lb52 bt RX worker exit window hit\n");
 786	    }
 787	
 788	#if SF32LB52_BT_TRACE
 789	  {
 790	    struct circular_buf *rx_ring =
 791	        (struct circular_buf *)SF32LB52_BT_RX_BUF_ADDR;
 792	
 793	    up_invalidate_dcache((uintptr_t)SF32LB52_BT_RX_BUF_ADDR,
 794	                         (uintptr_t)SF32LB52_BT_RX_BUF_ADDR +
 795	                         sizeof(*rx_ring));
 796	
 797	    syslog(LOG_INFO,
 798	           "sf32lb52 rx_ind: size=%lu local=%08lx rd=%08lx wr=%08lx\n",
 799	           (unsigned long)size,
 800	           (unsigned long)env->rx_read_idx_mirror,
 801	           (unsigned long)rx_ring->read_idx_mirror,
 802	           (unsigned long)rx_ring->write_idx_mirror);
 803	  }
 804	#endif
 805	
 806	  if (queue_work)
 807	    {
 808	      int ret;
 809	
 810	      ret = work_queue(HPWORK, &env->rx_work, sf32lb52_bt_rx_worker,
 811	                       env, 0);
 812	      if (ret < 0)
 813	        {
 814	          flags = enter_critical_section();
 815	          env->rx_worker_running = false;
 816	          leave_critical_section(flags);
 817	
 818	          syslog(LOG_ERR, "sf32lb52 bt queue rx work failed: %d\n", ret);
 819	          return ret;
 820	        }
 821	    }
 822	
 823	  return OK;
 824	}
