   418	static uint32_t sf32lb52_bt_ring_advance(uint32_t ptr, size_t len,
   419	                                         uint32_t buffer_size)
   420	{
   421	  uint32_t idx = CB_GET_PTR_IDX(ptr);
   422	  uint32_t mirror = CB_GET_PTR_MIRROR(ptr);
   423	
   424	  idx += len;
   425	  if (idx >= buffer_size)
   426	    {
   427	      idx -= buffer_size;
   428	      mirror = ~mirror;
   429	    }
   430	
   431	  return CB_MAKE_PTR_IDX_MIRROR(idx, mirror);
   432	}
   433	
   434	static size_t sf32lb52_bt_ring_copy(uint8_t *dst,
   435	                                    const struct circular_buf *rx_ring,
   436	                                    uint32_t rd_ptr,
   437	                                    size_t len)
   438	{
   439	  const uint8_t *pool = (const uint8_t *)(rx_ring + 1);
   440	  uint32_t rd_idx = CB_GET_PTR_IDX(rd_ptr);
   441	  size_t tail;
   442	
   443	  if (len == 0)
   444	    {
   445	      return 0;
   446	    }
   447	
   448	  tail = rx_ring->buffer_size - rd_idx;
   449	  if (tail >= len)
   450	    {
   451	      memcpy(dst, &pool[rd_idx], len);
   452	      return len;
   453	    }
   454	
   455	  memcpy(dst, &pool[rd_idx], tail);
   456	  memcpy(&dst[tail], pool, len - tail);
   457	  return len;
   458	}
   459	
   460	static size_t sf32lb52_bt_ring_write(struct circular_buf *tx_ring,
   461	                                     const uint8_t *src, size_t len)
   462	{
   463	  uint8_t *pool = (uint8_t *)(tx_ring + 1);
   464	  uint32_t wr_ptr = tx_ring->write_idx_mirror;
   465	  uint32_t wr_idx = CB_GET_PTR_IDX(wr_ptr);
   466	  size_t space;
   467	  size_t tail;
   468	
   469	  space = sf32lb52_bt_ring_space_len(tx_ring->read_idx_mirror,
   470	                                     wr_ptr,
   471	                                     tx_ring->buffer_size);
   472	  if (space == 0)
   473	    {
   474	      return 0;
   475	    }
   476	
   477	  if (len > space)
   478	    {
   479	      len = space;
   480	    }
   481	
   482	  tail = tx_ring->buffer_size - wr_idx;
   483	  if (tail >= len)
   484	    {
   485	      memcpy(&pool[wr_idx], src, len);
   486	      up_clean_dcache((uintptr_t)&pool[wr_idx],
   487	                      (uintptr_t)&pool[wr_idx] + len);
   488	    }
   489	  else
   490	    {
   491	      memcpy(&pool[wr_idx], src, tail);
   492	      memcpy(pool, &src[tail], len - tail);
   493	      up_clean_dcache((uintptr_t)&pool[wr_idx],
   494	                      (uintptr_t)&pool[wr_idx] + tail);
   495	      up_clean_dcache((uintptr_t)pool,
   496	                      (uintptr_t)pool + len - tail);
   497	    }
   498	
   499	  tx_ring->write_idx_mirror = sf32lb52_bt_ring_advance(wr_ptr, len,
   500	                                                       tx_ring->buffer_size);
   501	  up_clean_dcache((uintptr_t)tx_ring,
   502	                  (uintptr_t)tx_ring + sizeof(*tx_ring));
   503	  __DSB();
   504	
   505	  return len;
   506	}
