   524	      *rd_ptr = rd;
   525	    }
   526	
   527	  if (wr_ptr != NULL)
   528	    {
   529	      *wr_ptr = wr;
   530	    }
   600	    {
   601	      return 1;
   602	    }
   603	
   604	  return remaining;
   605	}
