   826	static int sf32lb52_bt_mailbox_init(void)
   827	{
   828	  struct sf32lb52_bt_env_s *env = &g_sf32lb52_bt_env;
   829	  ipc_queue_cfg_t q_cfg;
   830	
   930	  if (g_sf32lb52_bt_status == SF32LB52_BT_STATUS_ENABLED)
   931	    {
   932	      return OK;
   933	    }
   934	
   935	  if (g_sf32lb52_bt_status != SF32LB52_BT_STATUS_INITED)
   936	    {
   937	      return -EPERM;
   938	    }
   939	
   940	  sf32lb52_bt_prepare_stack_nvds();
   941	  HAL_LCPU_ASSERT_INFO_clear();
   942	
   943	  ret = lcpu_power_on();
   944	  if (ret != 0)
   945	    {
   946	      return -EIO;
   947	    }
   948	
   949	  /* The L2H_MAILBOX (0x40002000) is on the LPSYS APB bus.  Its CxIER
   950	   * register is only writable when the LPSYS bus bridge is active.
   951	   * Wake the LCPU first so the bus bridge is powered, THEN open the
   952	   * IPC queue (which writes CxIER to unmask the mailbox RX interrupt).
   953	   * The SDK reference ipc_hw_enable_interrupt2() has the same
   954	   * HAL_HPAON_WakeCore() before the UNMASK call.
   955	   */
   956	
   957	  HAL_HPAON_WakeCore(CORE_ID_LCPU);
   958	  g_sf32lb52_bt_env.wake_held = true;
   959	
   960	  usleep(500000);
   961	
   962	  ret = ipc_queue_open(g_sf32lb52_bt_env.ipc_port);
   963	  if (ret < 0)
   964	    {
   965	      HAL_HPAON_CANCEL_LP_ACTIVE_REQUEST();
   966	      g_sf32lb52_bt_env.wake_held = false;
   967	      return ret;
   968	    }
   969	
   970	  /* Flush H2L TX ring to SRAM immediately after ipc_queue_open so
   971	   * LCPU sees the reset indices (read_idx=write_idx=0) before it
   972	   * tries to process any stale data from a previous session.
   973	   */
   974	  up_clean_dcache((uintptr_t)SF32LB52_BT_TX_BUF_ADDR,
   975	                  (uintptr_t)SF32LB52_BT_TX_BUF_ADDR +
   976	                  SF32LB52_BT_TX_BUF_SIZE);
   977	  __DSB();
   978	
   979	  /* After every lcpu_power_on(), LCPU resets its TX ring write pointer
   980	   * (write_idx_mirror) to 0 and writes its own boot responses into the
   981	   * ring.  HCPU's read pointer (read_idx_mirror) may still hold the
   982	   * non-zero value from the previous session -- dirty in DCache or
   983	   * stored in SRAM.  If we do not synchronise them:
   984	   *
   985	   *   circular_buf_data_len() = wrap(write_idx - read_idx)
   986	   *
   987	   * returns a large garbage value, and LCPU's fresh boot events
   988	   * plus ring garbage all replay as "new" HCI responses.  These
   989	   * ghost events are consumed by the host as replies to real commands,
   990	   * so HCI_Reset (0x0c01) is never actually executed by the controller,
   991	   * and bt_le_adv_start later gets "Command Disallowed" (0x07).
   992	   *
   993	   * Fix: flush DCache to write back any dirty read_idx and to load
   994	   * LCPU's current write_idx from SRAM, then advance read_idx to
   995	   * write_idx (discard ALL pending LCPU boot data), then clean the
   996	   * DCa…1506 tokens truncated…, cb->buffer_size - wr_idx);
   142	    memcpy(&cb->wr_buffer_ptr[0], &ptr[cb->buffer_size - wr_idx],
   143	           length - (cb->buffer_size - wr_idx));
   144	
   145	    wr_mirror = ~wr_mirror;
   146	    wr_idx = length - (cb->buffer_size - wr_idx);
   147	    cb->write_idx_mirror = CB_MAKE_PTR_IDX_MIRROR(wr_idx, wr_mirror);
   148	
   149	    if (length > space_length)
   150	    {
   151	        rd_mirror = CB_GET_PTR_MIRROR(cb->read_idx_mirror);
   152	        rd_mirror = ~rd_mirror;
   153	        cb->read_idx_mirror = CB_MAKE_PTR_IDX_MIRROR(wr_idx, rd_mirror);
   154	    }
   155	
   156	    return length;
   157	}
   158	
   159	__ROM_USED size_t circular_buf_get(struct circular_buf *cb, uint8_t *ptr,
   160	                                   uint16_t length)
   161	{
   162	    size_t size;
   163	    uint32_t rd_mirror;
   164	    uint32_t rd_idx;
   165	
   166	    SF_ASSERT(cb != NULL);
   167	
   168	    size = circular_buf_data_len(cb);
   169	    if (size == 0)
   170	    {
