   133	static bool sf32lb52_bt_rx_ring_valid(struct circular_buf *rx_ring)
   134	{
   135	  uint32_t rd_ptr = rx_ring->read_idx_mirror;
   136	  uint32_t wr_ptr = rx_ring->write_idx_mirror;
   137	  uint32_t rd_idx = CB_GET_PTR_IDX(rd_ptr);
   138	  uint32_t wr_idx = CB_GET_PTR_IDX(wr_ptr);
   139	  long buf_size = rx_ring->buffer_size;
   140	
   141	  return buf_size == (long)SF32LB52_BT_RING_DATA_SIZE &&
   142	         rd_idx <= SF32LB52_BT_RING_DATA_SIZE &&
   143	         wr_idx <= SF32LB52_BT_RING_DATA_SIZE;
   144	}
