   411	static size_t sf32lb52_bt_ring_space_len(uint32_t rd_ptr, uint32_t wr_ptr,
   412	                                         uint32_t buffer_size)
   413	{
   414	  return buffer_size - sf32lb52_bt_ring_data_len(rd_ptr, wr_ptr,
