   508	static size_t sf32lb52_bt_tx_pending(struct circular_buf *tx_ring,
   509	                                     uint32_t *rd_ptr,
   510	                                     uint32_t *wr_ptr)
   511	{
   512	  uint32_t rd;
   513	  uint32_t wr;
   514	
   515	  up_invalidate_dcache((uintptr_t)SF32LB52_BT_TX_BUF_ADDR,
   516	                       (uintptr_t)SF32LB52_BT_TX_BUF_ADDR +
   517	                       sizeof(*tx_ring));
   518	
   519	  rd = tx_ring->read_idx_mirror;
   520	  wr = tx_ring->write_idx_mirror;
   521	
   522	  if (rd_ptr != NULL)
   523	    {
   524	      *rd_ptr = rd;
   525	    }
   526	
   527	  if (wr_ptr != NULL)
   528	    {
   529	      *wr_ptr = wr;
   530	    }
   600	    {
   601	      return 1;
   602	    }
   603	
   604	  return remaining;
   605	}
