    51	    }
    52	
    53	    ch = &ipc_hw_obj.ch[ch_id];
    54	    ch_cfg = &ch->cfg;
    55	    q_idx = qid - ch_id * IPC_HW_QUEUE_NUM;
    56	    ch->data.user_data[q_idx] = user_data;
    57	    ch->data.act_bitmap |= (1UL << q_idx);
    58	    hw_q_handle->ch_id = ch_id;
    59	    hw_q_handle->q_idx = q_idx;
    60	
    61	    os_interrupt_start(ch_cfg->rx.irqn, 3, 0);
    62	
    63	    /* Unmask H2L (HCPU->LCPU) so LCPU's mailbox IRQ fires when HCPU writes
    64	     * CxITR.  Per SiFli-SDK reference, each side unmasks its own TX mailbox
    65	     * (the remote side's receive path) at open time.  The original vendor
    66	     * copy incorrectly used rx.handle here, leaving H2L.CxIER=0 and LCPU
    67	     * deaf to all H2L triggers (CxISR would be set but CxMISR stayed 0).
    68	     */
    69	    __HAL_MAILBOX_UNMASK_CHANNEL_IT(&ch_cfg->tx.handle, q_idx);
    70	
    71	    /* Also unmask L2H (LCPU->HCPU) so HCPU receives LCPU notifications.
    72	     * In the SiFli-SDK reference design LCPU unmasks L2H from its own side,
    73	     * but we do it here too as a safety net for LCPU firmwares that skip it.
    74	     */
    75	    __HAL_MAILBOX_UNMASK_CHANNEL_IT(&ch_cfg->rx.handle, q_idx);
    76	
    77	    result = 0;
    78	    return result;
    79	}
