+static void sf32lb52_bt_diag_rx_feed(const uint8_t *data, size_t len)
+{
+  struct sf32lb52_bt_rx_diag_s *diag = &g_sf32lb52_bt_rx_diag;
+  size_t i;
+
+  for (i = 0; i < len; i++)
+    {
+      int packet_len;
+
+      if (diag->packet_len == sizeof(diag->packet))
+        {
+          diag->packet_len = 0;
+        }
+
+      diag->packet[diag->packet_len++] = data[i];
+
+      for (;;)
+        {
+          packet_len = sf32lb52_bt_diag_h4_packet_len(diag->packet,
+                                                       diag->packet_len);
+          if (packet_len == 0)
+            {
+              break;
+            }
+
+          if (packet_len < 0 || packet_len > sizeof(diag->packet))
+            {
+              memmove(diag->packet, &diag->packet[1],
+                      --diag->packet_len);
+              continue;
+            }
+
+          if ((size_t)packet_len > diag->packet_len)
+            {
+              break;
+            }
+
+          if (diag->packet[0] == H4_ACL)
+            {
+              sf32lb52_bt_diag_acl_data_rx(diag->packet, packet_len);
+            }
+
+          diag->packet_len -= packet_len;
+          memmove(diag->packet, &diag->packet[packet_len],
+                  diag->packet_len);
+        }
+    }
+}
