129	__WEAK void mpu_config(void)
130	{
131	//#if defined (__DCACHE_PRESENT) && (__DCACHE_PRESENT == 1U)
132	    uint32_t rnr, rbar, rlar;
133	
134	
135	    SCB_DisableDCache();
136	    SCB_DisableICache();
137	
138	    ARM_MPU_Disable();
139	
140	    mpu_clear_region();
141	
142	    ARM_MPU_SetMemAttr(ATTR_CODE_IDX, ATTR_CODE);
143	    ARM_MPU_SetMemAttr(ATTR_RAM_IDX, ATTR_RAM);
144	    ARM_MPU_SetMemAttr(ATTR_DEVICE_IDX, ATTR_DEVICE);
145	    ARM_MPU_SetMemAttr(ATTR_PSRAM_WB_IDX, ATTR_PSRAM_WB);
146	    ARM_MPU_SetMemAttr(ATTR_PSRAM_WT_IDX, ATTR_PSRAM_WT);
147	
148	    rnr = 0;
149	
150	    //  hpsys rom
151	    rbar = ARM_MPU_RBAR(0x0, ARM_MPU_SH_NON, 1, 1, 1); //Non-shareable,RO,any privilege,executable
152	    rlar = ARM_MPU_RLAR(0x0000ffff, ATTR_CODE_IDX);
153	    ARM_MPU_SetRegion(rnr++, rbar, rlar);
154	
155	    // hpsys RETM/ITCM ram disable sram cache
156	    rbar = ARM_MPU_RBAR(0x00010000, ARM_MPU_SH_NON, 0, 1, 0); //Non-shareable,RW,any privilege,executable
157	    rlar = ARM_MPU_RLAR(0x0002ffff, ATTR_RAM_IDX);
158	    ARM_MPU_SetRegion(rnr++, rbar, rlar);
159	
160	#ifdef DUAL_FLASH
161	    //  flash1 and flash2 region a
162	    rbar = ARM_MPU_RBAR(0x10000000, ARM_MPU_SH_NON, 1, 1, 0); //Non-shareable,RO,any privilege,executable
163	    rlar = ARM_MPU_RLAR(0x12ffffff, ATTR_CODE_IDX);
164	    ARM_MPU_SetRegion(rnr++, rbar, rlar);
165	    //  flash2, region b
166	    rbar = ARM_MPU_RBAR(0x13000000, ARM_MPU_SH_NON, 1, 1, 0); //Non-shareable,RO,any privilege,executable
167	    rlar = ARM_MPU_RLAR(0x13ffffff, ATTR_RAM_IDX);
168	    ARM_MPU_SetRegion(rnr++, rbar, rlar);
169	#else
170	    //  flash1 and flash2
171	    rbar = ARM_MPU_RBAR(0x10000000, ARM_MPU_SH_NON, 1, 1, 0); //Non-shareable,RO,any privilege,executable
172	    rlar = ARM_MPU_RLAR(0x1fffffff, ATTR_CODE_IDX);
173	    ARM_MPU_SetRegion(rnr++, rbar, rlar);
174	#endif /* DUAL_FLASH */
175	
176	    // hpsys ram, disable sram cache
177	    rbar = ARM_MPU_RBAR(0x20000000, ARM_MPU_SH_NON, 0, 1, 0); //Non-shareable,RW,any privilege,executable
178	    rlar = ARM_MPU_RLAR(0x2027ffff, ATTR_RAM_IDX);
179	    ARM_MPU_SetRegion(rnr++, rbar, rlar);
180	
181	    // peripheral
182	    rbar = ARM_MPU_RBAR(0x40000000, ARM_MPU_SH_NON, 0, 1, 1); //Non-shareable,RW,any privilege,non-executable
183	    rlar = ARM_MPU_RLAR(0x5fffffff, ATTR_DEVICE_IDX);
184	    ARM_MPU_SetRegion(rnr++, rbar, rlar);
185	
186	    // psram
187	    rbar = ARM_MPU_RBAR(0x60000000, ARM_MPU_SH_NON, 0, 1, 0); //Non-shareable,RW,any privilege,executable
188	#ifdef PSRAM_CACHE_WB
189	    rlar = ARM_MPU_RLAR(0x61ffffff, ATTR_PSRAM_WB_IDX);
190	#else
191	    rlar = ARM_MPU_RLAR(0x61ffffff, ATTR_PSRAM_WT_IDX);
192	#endif
193	
194	    ARM_MPU_SetRegion(rnr++, rbar, rlar);
195	
196	    // lpsys ram
197	    rbar = ARM_MPU_RBAR(0x203fc000, ARM_MPU_SH_NON, 0, 1, 0); //Non-shareable,RW,any privilege,executable
198	    rlar = ARM_MPU_RLAR(0x204fffff, ATTR_RAM_IDX);
199	    ARM_MPU_SetRegion(rnr++, rbar, rlar);
200	
201	    // lpsys ITCM and CBUS
202	    rbar = ARM_MPU_RBAR(0x20bfc000, ARM_MPU_SH_NON, 0, 1, 0); //Non-shareable,RW,any privilege,executable
203	    rlar = ARM_MPU_RLAR(0x20cbffff, ATTR_RAM_IDX);
204	    ARM_MPU_SetRegion(rnr++, rbar, rlar);
205	
206	    // ble rom
207	    rbar = ARM_MPU_RBAR(0x20800000, ARM_MPU_SH_NON, 0, 1, 0); //Non-shareable,RW,any privilege,executable
208	    rlar = ARM_MPU_RLAR(0x208fffff, ATTR_CODE_IDX);
209	    ARM_MPU_SetRegion(rnr++, rbar, rlar);
210	
211	    // nand 2
212	    rbar = ARM_MPU_RBAR(0x62000000, ARM_MPU_SH_NON, 1, 1, 0); //Non-shareable,RO,any privilege,executable
213	    rlar = ARM_MPU_RLAR(0x6FFFFFFF, ATTR_RAM_IDX);
214	    ARM_MPU_SetRegion(rnr++, rbar, rlar);
215	
216	    HAL_ASSERT(rnr <= MPU_REGION_NUM);
217	    ARM_MPU_Enable(MPU_CTRL_HFNMIENA_Msk);
218	//#endif
219	
220	    SCB_EnableDCache();
221	    SCB_EnableICache();
222	}
